/* ==========================================================================
   MARGIN — Issue 14: Low Water (Autumn 2026)
   Contemporary Print Editorial Stylesheet (Local System Fonts & Zero Remote Assets)
   ========================================================================== */

:root,
html[data-theme="paper"] {
  --bg-page: #f4efe6;
  --bg-elevated: #ece5d8;
  --bg-plate: #efe8da;
  --ink: #171513;
  --ink-muted: #524c44;
  --ink-faint: #787065;
  --rule: #c8bfa8;
  --rule-strong: #171513;
  --accent: #b43c23;
  --accent-soft: rgba(180, 60, 35, 0.12);
  --channel-tint: rgba(44, 66, 73, 0.12);
  --success-bg: #e4ece4;
  --success-ink: #1d4726;
  --success-rule: #4b7b55;
  --error-bg: #f6e4e0;
  --error-ink: #8a2312;
  --error-rule: #b43c23;
  --focus-ring: #b43c23;
}

html[data-theme="ledger"] {
  --bg-page: #e6dcc6;
  --bg-elevated: #dcd0b6;
  --bg-plate: #dfd3b9;
  --ink: #14110d;
  --ink-muted: #453e34;
  --ink-faint: #675e50;
  --rule: #b5a88c;
  --rule-strong: #14110d;
  --accent: #982f18;
  --accent-soft: rgba(152, 47, 24, 0.14);
  --channel-tint: rgba(38, 59, 66, 0.15);
  --success-bg: #d7e2d4;
  --success-ink: #173d1f;
  --success-rule: #3e6b47;
  --error-bg: #eed8d2;
  --error-ink: #781c0c;
  --error-rule: #982f18;
  --focus-ring: #982f18;
}

html[data-theme="nocturne"] {
  --bg-page: #131415;
  --bg-elevated: #1b1d1f;
  --bg-plate: #181a1c;
  --ink: #ece6d9;
  --ink-muted: #b3ab9c;
  --ink-faint: #847d70;
  --rule: #34322d;
  --rule-strong: #ece6d9;
  --accent: #e06346;
  --accent-soft: rgba(224, 99, 70, 0.18);
  --channel-tint: rgba(116, 162, 179, 0.14);
  --success-bg: #18291d;
  --success-ink: #a9dfb4;
  --success-rule: #3e784a;
  --error-bg: #2e1916;
  --error-ink: #f6a494;
  --error-rule: #e06346;
  --focus-ring: #e06346;
}

:root {
  --font-display: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, "URW Palladio L", Georgia, serif;
  --font-serif: Charter, "Bitstream Charter", "Sitka Text", Cambria, Georgia, serif;
  --font-mono: "SF Mono", "JetBrains Mono", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;

  --scale-multiplier: 1;
  --line-measure: 62ch;
  --margin-col-width: 176px;
}

html[data-scale="large"] {
  --scale-multiplier: 1.12;
}

/* Reset & Base */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: calc(16px * var(--scale-multiplier));
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background-color: var(--bg-page);
  color: var(--ink);
  font-family: var(--font-serif);
  line-height: 1.6;
  transition: background-color 180ms ease, color 180ms ease;
  overflow-x: hidden;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}

/* Accessibility Helpers */
.skip-link {
  position: absolute;
  top: -3.5rem;
  left: 1rem;
  z-index: 1000;
  background: var(--ink);
  color: var(--bg-page);
  padding: 0.6rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  text-decoration: none;
  border: 2px solid var(--accent);
}

.skip-link:focus {
  top: 0.75rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 3px;
}

/* Quiet Margin (Focus Reading Mode) */
html[data-focus="on"] .masthead__margin-col,
html[data-focus="on"] .cover-spread__margin,
html[data-focus="on"] .toc-section__margin,
html[data-focus="on"] .subscription-spread__margin,
html[data-focus="on"] .story-entry__diagram {
  opacity: 0.28;
  transition: opacity 200ms ease;
}

html[data-focus="on"] .masthead__margin-col:hover,
html[data-focus="on"] .cover-spread__margin:hover,
html[data-focus="on"] .toc-section__margin:hover,
html[data-focus="on"] .subscription-spread__margin:hover {
  opacity: 1;
}

/* Shared Editorial Typography */
.mono-tag {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--ink-muted);
}

.folio-number {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
  letter-spacing: 0.04em;
}

.section-rubric {
  margin: 0 0 0.5rem 0;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink);
}

.author-name {
  font-variant: small-caps;
  letter-spacing: 0.04em;
  font-weight: 600;
}

/* ==========================================================================
   Top Utility & Reading Mode Bar
   ========================================================================== */
.utility-bar {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: var(--bg-page);
  border-bottom: 1px solid var(--rule);
}

.utility-bar__inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0.55rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.utility-bar__meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.utility-sep {
  color: var(--rule);
  font-size: 0.75rem;
}

.reading-controls {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.reading-controls__group {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.reading-controls__label {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-faint);
  margin-right: 0.25rem;
}

.reading-controls__divider {
  width: 1px;
  height: 1rem;
  background-color: var(--rule);
}

.mode-btn {
  appearance: none;
  background: transparent;
  color: var(--ink-muted);
  border: 1px solid var(--rule);
  padding: 0.24rem 0.55rem;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.04em;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  transition: background-color 120ms ease, color 120ms ease, border-color 120ms ease;
}

.mode-btn:hover {
  color: var(--ink);
  border-color: var(--ink-muted);
}

.mode-btn[aria-pressed="true"] {
  background-color: var(--ink);
  color: var(--bg-page);
  border-color: var(--ink);
}

.mode-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  border: 1px solid currentColor;
  display: inline-block;
}

.mode-dot--paper {
  background-color: #f4efe6;
}

.mode-dot--ledger {
  background-color: #decfa6;
}

.mode-dot--nocturne {
  background-color: #181a1c;
}

/* ==========================================================================
   Main Page Frame & Masthead
   ========================================================================== */
.page-frame {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 1.5rem 4rem;
}

.masthead {
  border-bottom: 2px solid var(--rule-strong);
  padding: 2.25rem 0 2rem;
}

.masthead__grid {
  display: grid;
  grid-template-columns: var(--margin-col-width) 1fr 290px;
  gap: 2rem;
  align-items: end;
}

.masthead__margin-col {
  border-right: 1px solid var(--rule);
  padding-right: 1rem;
  align-self: stretch;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.folio-mark,
.folio-sub,
.folio-datum {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.73rem;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
}

.folio-mark {
  font-weight: 700;
  color: var(--ink);
}

.folio-sub {
  color: var(--ink-muted);
}

.folio-datum {
  color: var(--accent);
  font-weight: 600;
}

.masthead__wordmark {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(3.6rem, 8vw, 6.75rem);
  font-weight: 400;
  line-height: 0.88;
  letter-spacing: -0.03em;
}

.masthead__tagline {
  margin: 0.85rem 0 0;
  max-width: 44ch;
  font-size: 1.02rem;
  line-height: 1.45;
  color: var(--ink-muted);
}

.issue-spec {
  margin: 0;
  border-top: 1px solid var(--rule-strong);
  font-size: 0.85rem;
}

.issue-spec__row {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.38rem 0;
  border-bottom: 1px solid var(--rule);
}

.issue-spec__row dt {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-muted);
}

.issue-spec__row dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.spec-link {
  color: var(--accent);
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 600;
}

.spec-link:hover {
  text-decoration: underline;
}

/* ==========================================================================
   Cover Story & Bathymetric Plate Spread
   ========================================================================== */
.cover-spread {
  display: grid;
  grid-template-columns: var(--margin-col-width) minmax(0, 1.05fr) minmax(0, 1.15fr);
  gap: 2rem;
  padding: 2.5rem 0 3rem;
  border-bottom: 2px solid var(--rule-strong);
}

.cover-spread__margin {
  border-right: 1px solid var(--rule);
  padding-right: 1rem;
}

.margin-note {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.margin-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

.margin-caption {
  margin: 0.35rem 0 0;
  font-size: 0.82rem;
  line-height: 1.45;
  color: var(--ink-muted);
}

.cover-spread__narrative {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}

.issue-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding-bottom: 0.65rem;
  margin-bottom: 1.25rem;
  border-bottom: 1px solid var(--rule);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.issue-banner__kicker {
  color: var(--ink-muted);
}

.issue-banner__theme {
  color: var(--accent);
  font-weight: 700;
}

.cover-header__rubric {
  margin: 0 0 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
}

.cover-header__title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.15rem, 3.8vw, 3.45rem);
  font-weight: 400;
  line-height: 1.06;
  letter-spacing: -0.015em;
}

.cover-header__byline {
  margin: 0.85rem 0 0;
  font-size: 1rem;
  color: var(--ink-muted);
}

.cover-deck {
  margin: 1.35rem 0 1.75rem;
  font-size: 1.18rem;
  line-height: 1.58;
  max-width: var(--line-measure);
  color: var(--ink);
}

.cover-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
}

.editorial-btn {
  appearance: none;
  font-family: var(--font-mono);
  font-size: 0.76rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.75rem 1.1rem;
  border: 1px solid var(--rule-strong);
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}

.editorial-btn--primary {
  background-color: var(--ink);
  color: var(--bg-page);
}

.editorial-btn--primary:hover {
  background-color: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.editorial-btn--ghost {
  background-color: transparent;
  color: var(--ink);
}

.editorial-btn--ghost:hover {
  background-color: var(--bg-elevated);
}

/* Expandable Specimen Excerpt */
.reading-specimen {
  margin-top: 1.75rem;
  padding: 1.35rem 1.4rem;
  background-color: var(--bg-elevated);
  border-left: 3px solid var(--accent);
  border-top: 1px solid var(--rule);
  border-right: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}

.reading-specimen__header {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  padding-bottom: 0.65rem;
  margin-bottom: 0.9rem;
  border-bottom: 1px solid var(--rule);
}

.reading-specimen__body p {
  margin: 0 0 1rem;
  font-size: 0.98rem;
  line-height: 1.68;
  max-width: var(--line-measure);
}

.dropcap-para::first-letter {
  float: left;
  font-family: var(--font-display);
  font-size: 3.1rem;
  line-height: 0.82;
  padding-right: 0.45rem;
  padding-top: 0.15rem;
  color: var(--accent);
}

.specimen-pullquote {
  margin: 1rem 0 0;
  padding-top: 0.75rem;
  border-top: 1px solid var(--rule);
  font-family: var(--font-display);
  font-style: italic;
  font-size: 1.06rem;
  line-height: 1.45;
  color: var(--ink);
}

/* Survey Plate (Display Motif) */
.survey-plate {
  margin: 0;
  background-color: var(--bg-plate);
  border: 1px solid var(--rule-strong);
  display: flex;
  flex-direction: column;
}

.survey-plate__topbar {
  padding: 0.55rem 0.85rem;
  border-bottom: 1px solid var(--rule);
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.survey-plate__canvas {
  padding: 0.75rem;
}

.bathymetry-svg {
  width: 100%;
  height: auto;
  display: block;
  color: var(--ink);
}

.svg-mono-label {
  font-family: var(--font-mono);
  letter-spacing: 0.05em;
}

.svg-accent-line {
  stroke: var(--accent);
}

.svg-accent-text {
  fill: var(--accent);
}

.svg-accent-fill {
  fill: var(--accent);
}

.low-water-channel {
  fill: var(--channel-tint);
  stroke: var(--ink);
  stroke-width: 0.9;
}

.artifact-node {
  cursor: pointer;
}

.artifact-ring {
  fill: var(--bg-plate);
  stroke: var(--ink);
  stroke-width: 1.2;
  transition: stroke 140ms ease, fill 140ms ease;
}

.artifact-core {
  fill: var(--ink);
}

.artifact-node.is-active .artifact-ring {
  stroke: var(--accent);
  stroke-width: 2;
  fill: var(--accent-soft);
}

.artifact-node.is-active .artifact-core {
  fill: var(--accent);
}

.survey-plate__caption {
  border-top: 1px solid var(--rule);
  background-color: var(--bg-elevated);
}

.artifact-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-bottom: 1px solid var(--rule);
}

.artifact-tab {
  appearance: none;
  background: transparent;
  border: none;
  border-right: 1px solid var(--rule);
  padding: 0.55rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.69rem;
  color: var(--ink-muted);
  cursor: pointer;
  text-align: left;
  transition: background-color 120ms ease, color 120ms ease;
}

.artifact-tab:last-child {
  border-right: none;
}

.artifact-tab:hover {
  color: var(--ink);
  background-color: var(--bg-page);
}

.artifact-tab.is-active {
  background-color: var(--bg-page);
  color: var(--accent);
  font-weight: 700;
}

.artifact-readout {
  padding: 0.75rem 0.9rem;
}

.artifact-readout__coord {
  margin: 0 0 0.25rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  color: var(--accent);
}

.artifact-readout__note {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.45;
  color: var(--ink);
}

/* ==========================================================================
   Supporting Stories / Table of Contents
   ========================================================================== */
.toc-section {
  display: grid;
  grid-template-columns: var(--margin-col-width) 1fr;
  gap: 2rem;
  padding: 2.5rem 0;
  border-bottom: 2px solid var(--rule-strong);
}

.toc-section__margin {
  border-right: 1px solid var(--rule);
  padding-right: 1rem;
}

.toc-section__list {
  display: flex;
  flex-direction: column;
}

.story-entry {
  display: grid;
  grid-template-columns: 165px 1fr 130px;
  gap: 1.5rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--rule);
  align-items: start;
}

.story-entry:first-child {
  padding-top: 0;
}

.story-entry:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.story-entry__meta {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.story-entry__dept {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  color: var(--ink-muted);
}

.story-entry__title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.35rem, 2.2vw, 1.75rem);
  font-weight: 400;
  line-height: 1.18;
}

.story-entry__byline {
  margin: 0.3rem 0 0.6rem;
  font-size: 0.9rem;
  color: var(--ink-muted);
}

.story-entry__summary {
  margin: 0;
  font-size: 0.98rem;
  line-height: 1.55;
  max-width: 58ch;
  color: var(--ink);
}

.story-entry__diagram {
  border: 1px solid var(--rule);
  background-color: var(--bg-plate);
  padding: 0.35rem;
}

.mini-motif {
  width: 100%;
  height: auto;
  display: block;
  color: var(--ink);
}

/* ==========================================================================
   Compact Archive Strip (Issues 11–13)
   ========================================================================== */
.archive-strip {
  padding: 1.75rem 0;
  border-bottom: 2px solid var(--rule-strong);
}

.archive-strip__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
}

.archive-strip__note {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--ink-muted);
}

.archive-strip__grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid var(--rule-strong);
  background-color: var(--bg-elevated);
}

.archive-card {
  padding: 1rem 1.15rem;
  border-right: 1px solid var(--rule);
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.archive-card:last-child {
  border-right: none;
}

.archive-card__top {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.archive-card__issue {
  font-weight: 700;
  color: var(--accent);
}

.archive-card__season {
  color: var(--ink-muted);
}

.archive-card__title {
  margin: 0.15rem 0 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 400;
  line-height: 1.25;
}

.archive-card__meta {
  margin: 0;
  font-size: 0.84rem;
  line-height: 1.42;
  color: var(--ink-muted);
}

/* ==========================================================================
   Subscription Spread & Inline Email Validation Form
   ========================================================================== */
.subscription-spread {
  display: grid;
  grid-template-columns: var(--margin-col-width) 1.05fr 1fr;
  gap: 2rem;
  padding: 2.75rem 0;
  border-bottom: 2px solid var(--rule-strong);
}

.subscription-spread__margin {
  border-right: 1px solid var(--rule);
  padding-right: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.subscription-kicker {
  margin: 0 0 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
